
-- Migration 001: Create the products table
-- Each row represents a product in the Nebula shop.

CREATE TABLE products (
    -- Unique product ID, automatically generated by PostgreSQL.
    -- BIGINT supports 64-bit integers.
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Product name cannot be NULL, empty, or whitespace-only.
    -- TRIM removes surrounding spaces for validation.
    -- LENGTH checks that at least one character remains.
    name TEXT NOT NULL
        CHECK (length(trim(name)) > 0),

    -- If omitted, description defaults to an empty string.
    description TEXT NOT NULL DEFAULT '',

    -- Prices use whole Pawstars (PWS), without decimals.
    -- Negative prices are not allowed.
    price_pawstars INTEGER NOT NULL
        CHECK (price_pawstars >= 0),

    -- Category must contain at least one non-space character.
    category TEXT NOT NULL
        CHECK (length(trim(category)) > 0),

    -- Available inventory, initially zero if not provided.
    stock_quantity INTEGER NOT NULL DEFAULT 0
        CHECK (stock_quantity >= 0),

    -- Determines whether the product is active.
    is_active BOOLEAN NOT NULL DEFAULT TRUE,

    -- Automatically records when the product is created.
    -- TIMESTAMPTZ represents a time-zone-aware instant.
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Index intended to help queries filtering by active status
-- and category, potentially also ordering by product ID.
-- Its usefulness will be evaluated with EXPLAIN ANALYZE.
CREATE INDEX products_active_category_idx
ON products (is_active, category, id);
